script:
test("end date is included and a covered visit leaves one", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-30"
  });
  assert.deepEqual(actual, { covered: true, remaining: 1 });
});

test("one day after the end date is not covered and leaves two", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-05-01"
  });
  assert.deepEqual(actual, { covered: false, remaining: 2 });
});

test("used equal to approved is not covered and leaves zero", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 6,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-15"
  });
  assert.deepEqual(actual, { covered: false, remaining: 0 });
});

test("start date is included and a covered visit leaves one", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-01"
  });
  assert.deepEqual(actual, { covered: true, remaining: 1 });
});

test("a middle date is covered when used is below approved and leaves four", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 1,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-15"
  });
  assert.deepEqual(actual, { covered: true, remaining: 4 });
});

test("December 31 before a January 1 start is not covered and leaves three", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 2,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2025-12-31"
  });
  assert.deepEqual(actual, { covered: false, remaining: 3 });
});

test("January 1 exactly the start is covered and leaves two", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 2,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-01-01"
  });
  assert.deepEqual(actual, { covered: true, remaining: 2 });
});

test("January 30 one day before the end is covered and leaves two", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 2,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-01-30"
  });
  assert.deepEqual(actual, { covered: true, remaining: 2 });
});

test("January 31 exactly the end is covered and leaves two", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 2,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-01-31"
  });
  assert.deepEqual(actual, { covered: true, remaining: 2 });
});

test("February 1 one day after a January 31 end is not covered and leaves three", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 5,
    usedVisits: 2,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-02-01"
  });
  assert.deepEqual(actual, { covered: false, remaining: 3 });
});

test("leap day as a single-day window is covered and leaves three", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 7,
    usedVisits: 3,
    startDate: "2024-02-29",
    endDate: "2024-02-29",
    visitDate: "2024-02-29"
  });
  assert.deepEqual(actual, { covered: true, remaining: 3 });
});

test("one day before a leap-day start is not covered and leaves four", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 7,
    usedVisits: 3,
    startDate: "2024-02-29",
    endDate: "2024-02-29",
    visitDate: "2024-02-28"
  });
  assert.deepEqual(actual, { covered: false, remaining: 4 });
});

test("one day after a leap-day end is not covered and leaves four", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 7,
    usedVisits: 3,
    startDate: "2024-02-29",
    endDate: "2024-02-29",
    visitDate: "2024-03-01"
  });
  assert.deepEqual(actual, { covered: false, remaining: 4 });
});

test("zero approved and zero used inside the window is not covered and leaves zero", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 0,
    usedVisits: 0,
    startDate: "2026-06-01",
    endDate: "2026-06-30",
    visitDate: "2026-06-15"
  });
  assert.deepEqual(actual, { covered: false, remaining: 0 });
});

test("one approved and none used on the last day of June is covered and leaves zero", function () {
  var actual = code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: "2026-06-01",
    endDate: "2026-06-30",
    visitDate: "2026-06-30"
  });
  assert.deepEqual(actual, { covered: true, remaining: 0 });
});

test("an unknown field throws unknown field notes", function () {
  assert.throws(function () {
    code.checkAuthorization({
      approvedVisits: 6,
      usedVisits: 4,
      startDate: "2026-02-01",
      endDate: "2026-04-30",
      visitDate: "2026-03-15",
      notes: "extra"
    });
  }, /unknown field: notes/);
});
